function a(){const t=document.getElementById("calc-karat").value,n=parseFloat(document.getElementById("calc-weight").value)||0,l=parseFloat(document.getElementById("calc-making").value)||0,d=window.currentGram24K||315.5,m={24:1,22:22/24,21:21/24,18:18/24},o=d*m[t]*n,e=l*n,c=e*.15,r=o+e+c;document.getElementById("res-gold-val").textContent=o.toFixed(2),document.getElementById("res-making-val").textContent=e.toFixed(2),document.getElementById("res-tax-val").textContent=c.toFixed(2),document.getElementById("res-total-val").textContent=r.toFixed(2)}["calc-karat","calc-weight","calc-making"].forEach(t=>{document.getElementById(t)?.addEventListener("input",a)});window.recalculateGold=a;a();
